CREATE TABLE IF NOT EXISTS rtc_calls(id TEXT PRIMARY KEY,conversation_id BIGINT NOT NULL,caller_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,callee_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,kind TEXT NOT NULL CHECK(kind IN ('audio','video')),status TEXT NOT NULL DEFAULT 'ringing' CHECK(status IN ('ringing','answered','declined','ended','missed')),created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),answered_at TIMESTAMPTZ,ended_at TIMESTAMPTZ);
CREATE INDEX IF NOT EXISTS rtc_calls_callee_status_idx ON rtc_calls(callee_id,status,created_at DESC);
CREATE TABLE IF NOT EXISTS rtc_call_signals(id BIGSERIAL PRIMARY KEY,call_id TEXT NOT NULL REFERENCES rtc_calls(id) ON DELETE CASCADE,sender_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,recipient_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,kind TEXT NOT NULL CHECK(kind IN ('offer','answer','ice')),payload JSONB NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE INDEX IF NOT EXISTS rtc_call_signals_recipient_idx ON rtc_call_signals(call_id,recipient_id,id);
CREATE TABLE IF NOT EXISTS room_voice_presence(room_id BIGINT NOT NULL REFERENCES rooms(id) ON DELETE CASCADE,user_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,role TEXT NOT NULL DEFAULT 'listener' CHECK(role IN('listener','speaker')),requested BOOLEAN NOT NULL DEFAULT FALSE,muted BOOLEAN NOT NULL DEFAULT FALSE,joined_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),last_seen TIMESTAMPTZ NOT NULL DEFAULT NOW(),PRIMARY KEY(room_id,user_id));
CREATE INDEX IF NOT EXISTS room_voice_presence_active_idx ON room_voice_presence(room_id,last_seen DESC);
CREATE TABLE IF NOT EXISTS room_voice_signals(id BIGSERIAL PRIMARY KEY,room_id BIGINT NOT NULL REFERENCES rooms(id) ON DELETE CASCADE,sender_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,recipient_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,kind TEXT NOT NULL CHECK(kind IN('offer','answer','ice')),payload JSONB NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE INDEX IF NOT EXISTS room_voice_signals_recv_idx ON room_voice_signals(room_id,recipient_id,id);
